#[test]
fn fixes_from_3000_match_vanilla() {
    for &(ty, from, to, input, expected) in CASES_FROM_3000 {
        assert_eq!(update(ty, from, to, input), expected, "{ty} {from} -> {to}: {input}");
    }
}

#[test]
#[should_panic(expected = r#"Duplicate key NBT["minecraft:british"] (attempted merging values NBT["x"] and NBT["y"])"#)]
fn criteria_rename_rejects_duplicate_keys_like_vanilla() {
    update(
        "advancements",
        3085,
        3086,
        r#"{"minecraft:husbandry/complete_catalogue":{criteria:{"textures/entity/cat/british_shorthair.png":"x","minecraft:british":"y"},done:0b},DataVersion:3085}"#,
    );
}

#[test]
#[should_panic(expected = r#"Cannot invoke "String.isEmpty()" because "data" is null"#)]
fn frog_variant_without_a_name_fails_like_vanilla() {
    update("entity_chunk", 3086, 3087, r#"{Entities:[{id:"minecraft:frog",Variant:5}]}"#);
}
